/* tool-event-bridge.js — child-side helper for the interactive-tools
 * platform (Ticket, Address, Hotel, Date Check, Doner, and any later tool).
 *
 * A tool widget never writes to the analytics API directly. This file only
 * produces a postMessage to the parent page; js/tool-event-bridge-host.js
 * on the parent is the only thing that ever calls the backend
 * (/api?route=tool-event), and only after checking analytics consent.
 *
 * qualified_view is deliberately NOT exposed here: it is generated by the
 * parent bridge from real visibility + dwell time (>=50% visible for
 * >=1s), once per embedded instance, so a tool cannot self-report it.
 *
 * The message is sent to an EXACT target origin, never '*'. The only
 * signal a same-origin-restricted iframe has for its embedding page's
 * origin is document.referrer, so that is checked against the same
 * production/local-QA allowlist the backend uses; an unrecognized parent
 * origin means the message is not sent at all (fail closed).
 *
 * `actionName` must be empty or a member of the calling tool's own closed
 * enum (TOOL_ACTION_ENUMS below, mirroring TOOL_ACTION_ENUMS in
 * berlinwalk-content-app/api/_lib/tool-platform-shared.js) -- NOT a
 * regex/shape check. A shape check alone is not a safe boundary: values
 * like `Yusuf_Ucuz`, `HotelAdlon`, or `Unter_den_Linden_77` all satisfy a
 * "letters/digits/underscore" pattern while still being a real name, a
 * real hotel, and a real address. Metadata carries no string field at all
 * (numeric/boolean only). This client-side check is defense in depth, not
 * the only gate: the server re-validates everything regardless of what
 * this file does.
 *
 * Usage inside a tool widget:
 *   <script src="../js/tool-event-bridge.js"></script>
 *   <script>
 *     BWToolEvents.init({ toolSlug: 'berlin-address-time-machine' });
 *     BWToolEvents.track('start', { actionName: 'address_submitted', metadata: { stepIndex: 1 } });
 *   </script>
 */
(function (root, factory) {
  var api = factory();
  root.BWToolEvents = api;
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
})(typeof globalThis !== 'undefined' ? globalThis : this, function () {
  'use strict';

  // Must match TOOL_PLATFORM_CONTRACT_VERSION in
  // berlinwalk-content-app/api/_lib/tool-platform-shared.js and
  // CONTRACT_VERSION in tool-event-bridge-host.js -- the host rejects any
  // message whose `v` does not match its own copy of this exact string.
  var CONTRACT_VERSION = '20260830a';
  // Mirrors TOOL_EVENT_NAMES in berlinwalk-content-app/api/_lib/tool-platform-shared.js,
  // minus qualified_view (host-only, see file header).
  var CHILD_SENDABLE_EVENT_NAMES = ['start', 'complete', 'share_success', 'cta_click', 'action'];

  // Mirrors TOOL_PLATFORM_PRODUCTION_ORIGINS + TOOL_PLATFORM_LOCAL_QA_ORIGINS
  // in the backend's tool-platform-shared.js. A parent origin outside this
  // list never receives a message.
  var ALLOWED_PARENT_ORIGINS = [
    'https://www.berlinwalk.com',
    'https://berlinwalk.com',
    'http://localhost:5173',
    'http://127.0.0.1:5173',
    'http://localhost:8765',
    'http://127.0.0.1:8765',
  ];

  // Mirrors TOOL_ACTION_ENUMS in tool-platform-shared.js exactly. A closed,
  // reviewed, per-tool list -- not a shape check -- because a shape check
  // cannot tell `search_submitted` (safe) apart from `Yusuf_Ucuz` (a real
  // name) or `Unter_den_Linden_77` (a real address). berlin-dates-check's
  // list is empty on purpose: Date Check V2 stays on LeadAssetEvents, so
  // this bridge never carries a non-empty actionName for it.
  var TOOL_ACTION_ENUMS = {
    'berlin-ticket-machine-simulator': [
      'practice_selected', 'challenge_selected', 'scenario_started', 'answer_selected',
      'challenge_abandoned', 'replay_selected', 'share_opened',
    ],
    'berlin-address-time-machine': [
      'address_submitted', 'map_pin_selected', 'geolocation_selected', 'address_resolved',
      'layer_1989_selected', 'layer_today_selected', 'result_east', 'result_west',
      'result_near_border', 'result_outside_scope',
    ],
    'berlin-hotel-location-checker': [
      'address_submitted', 'map_pin_selected', 'priority_selected', 'address_resolved',
      'score_calculated', 'vbb_opened', 'article_opened', 'planner_opened', 'tour_opened',
    ],
    'berlin-dates-check': [],
    'berlin-doner-price-index': [
      'region_filter_selected', 'product_filter_selected', 'period_selected',
      'map_opened', 'source_opened',
    ],
  };
  var METADATA_INT_KEYS = { stepIndex: [0, 50], resultCount: [0, 999], durationMs: [0, 600000] };

  function isAllowedAction(toolSlug, actionName) {
    var allowed = TOOL_ACTION_ENUMS[toolSlug] || [];
    for (var i = 0; i < allowed.length; i += 1) {
      if (allowed[i] === actionName) return true;
    }
    return false;
  }

  function hex(byteCount) {
    var bytes;
    if (typeof crypto !== 'undefined' && crypto.getRandomValues) {
      bytes = new Uint8Array(byteCount);
      crypto.getRandomValues(bytes);
    } else {
      bytes = [];
      for (var i = 0; i < byteCount; i += 1) bytes.push(Math.floor(Math.random() * 256));
    }
    var out = '';
    for (var j = 0; j < bytes.length; j += 1) {
      var h = bytes[j].toString(16);
      out += h.length === 1 ? '0' + h : h;
    }
    return out;
  }

  function generateEventId() {
    return 'bwte_' + hex(16);
  }

  function detectToolSlugFromLocation(loc) {
    var path = ((loc && loc.pathname) || '').replace(/\/(index\.html?)?$/, '');
    var parts = path.split('/').filter(function (part) { return !!part; });
    return parts[parts.length - 1] || '';
  }

  function isValidEventName(name) {
    for (var i = 0; i < CHILD_SENDABLE_EVENT_NAMES.length; i += 1) {
      if (CHILD_SENDABLE_EVENT_NAMES[i] === name) return true;
    }
    return false;
  }

  // Same closed contract the server enforces: only
  // stepIndex/resultCount/durationMs/success (bounded numbers/boolean)
  // survive. There is no string field here at all -- a free or even a
  // token-shaped string is exactly the kind of thing that can carry a
  // name or a partial address. This is a courtesy filter; the server is
  // the real gate.
  function sanitizeMetadata(rawMetadata) {
    var result = {};
    if (!rawMetadata || typeof rawMetadata !== 'object' || Object.prototype.toString.call(rawMetadata) === '[object Array]') {
      return result;
    }
    for (var intKey in METADATA_INT_KEYS) {
      if (!Object.prototype.hasOwnProperty.call(METADATA_INT_KEYS, intKey)) continue;
      if (!Object.prototype.hasOwnProperty.call(rawMetadata, intKey)) continue;
      var bounds = METADATA_INT_KEYS[intKey];
      var n = Number(rawMetadata[intKey]);
      if (isFinite(n) && Math.floor(n) === n && n >= bounds[0] && n <= bounds[1]) result[intKey] = n;
    }
    if (Object.prototype.hasOwnProperty.call(rawMetadata, 'success') && typeof rawMetadata.success === 'boolean') {
      result.success = rawMetadata.success;
    }
    return result;
  }

  function buildToolEventMessage(toolSlug, eventName, opts) {
    opts = opts || {};
    var actionName = '';
    if (typeof opts.actionName === 'string' && opts.actionName && isAllowedAction(toolSlug, opts.actionName)) {
      actionName = opts.actionName;
    }
    return {
      type: 'bw-tool-event',
      v: CONTRACT_VERSION,
      toolSlug: toolSlug,
      eventName: eventName,
      actionName: actionName,
      metadata: sanitizeMetadata(opts.metadata),
      eventId: generateEventId(),
      ts: Date.now(),
    };
  }

  function referrerOrigin(doc) {
    try {
      if (!doc || !doc.referrer) return '';
      return new URL(doc.referrer).origin;
    } catch (e) {
      return '';
    }
  }

  function isAllowedParentOrigin(origin) {
    for (var i = 0; i < ALLOWED_PARENT_ORIGINS.length; i += 1) {
      if (ALLOWED_PARENT_ORIGINS[i] === origin) return true;
    }
    return false;
  }

  var state = { toolSlug: '' };

  function init(opts) {
    opts = opts || {};
    state.toolSlug = typeof opts.toolSlug === 'string' && opts.toolSlug
      ? opts.toolSlug
      : detectToolSlugFromLocation(typeof window !== 'undefined' ? window.location : null);
  }

  function warn(message) {
    if (typeof console !== 'undefined' && console.warn) console.warn(message);
  }

  function track(eventName, opts) {
    if (eventName === 'qualified_view') {
      warn('BWToolEvents.track: qualified_view is generated by the parent bridge, not the tool. Call ignored.');
      return false;
    }
    if (!isValidEventName(eventName)) {
      warn('BWToolEvents.track: unsupported event name "' + eventName + '". Call ignored.');
      return false;
    }
    if (typeof window === 'undefined' || window.parent === window) return false; // not embedded, nothing to post to
    if (!state.toolSlug) init();
    if (!state.toolSlug) {
      warn('BWToolEvents.track: no toolSlug set (call BWToolEvents.init({ toolSlug }) first). Call ignored.');
      return false;
    }
    var targetOrigin = referrerOrigin(typeof document !== 'undefined' ? document : null);
    if (!isAllowedParentOrigin(targetOrigin)) {
      warn('BWToolEvents.track: unrecognized parent origin, refusing to send.');
      return false;
    }
    var message = buildToolEventMessage(state.toolSlug, eventName, opts);
    try {
      window.parent.postMessage(message, targetOrigin);
      return true;
    } catch (e) {
      return false;
    }
  }

  return {
    CONTRACT_VERSION: CONTRACT_VERSION,
    EVENT_NAMES: CHILD_SENDABLE_EVENT_NAMES.slice(),
    ALLOWED_PARENT_ORIGINS: ALLOWED_PARENT_ORIGINS.slice(),
    init: init,
    track: track,
    // Exposed for unit tests and advanced callers; not part of the casual API surface.
    _internal: {
      detectToolSlugFromLocation: detectToolSlugFromLocation,
      isValidEventName: isValidEventName,
      isAllowedAction: isAllowedAction,
      sanitizeMetadata: sanitizeMetadata,
      buildToolEventMessage: buildToolEventMessage,
      generateEventId: generateEventId,
      referrerOrigin: referrerOrigin,
      isAllowedParentOrigin: isAllowedParentOrigin,
    },
  };
});
